$bytes = [Convert]::FromBase64String(($base64 -replace '\s',''))
[System.IO.File]::WriteAllBytes($Zip, $bytes)

$size = (Get-Item -LiteralPath $Zip).Length
$hash = (Get-FileHash -LiteralPath $Zip -Algorithm SHA256).Hash.ToUpper()
Write-Host "ZIP : $Zip"
Write-Host "SIZE: $size"
Write-Host "SHA : $hash"
if ($size -ne $ExpectedSize) { throw "Size mismatch. Expected $ExpectedSize got $size" }
if ($hash -ne $ExpectedSha) { throw "SHA mismatch. Expected $ExpectedSha got $hash" }

foreach ($name in @('x16x','x17x')) {
  $p = Join-Path $Repo $name
  if (Test-Path $p) { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue }
  $d = Join-Path $Desk $name
  if (Test-Path $d) { Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue }
}

Expand-Archive -LiteralPath $Zip -DestinationPath $Extract -Force
Copy-Item -Path (Join-Path $Extract 'lib') -Destination $Repo -Recurse -Force
Copy-Item -Path (Join-Path $Extract 'pubspec.yaml') -Destination $Repo -Force
Copy-Item -Path (Join-Path $Extract 'test') -Destination $Repo -Recurse -Force -ErrorAction SilentlyContinue

Copy-Item -Path (Join-Path $Repo 'lib') -Destination $Desk -Recurse -Force
Copy-Item -Path (Join-Path $Repo 'pubspec.yaml') -Destination $Desk -Force
Copy-Item -Path (Join-Path $Repo 'test') -Destination $Desk -Recurse -Force -ErrorAction SilentlyContinue

(Get-ChildItem -Path (Join-Path $Repo 'lib') -Recurse -Filter *.dart | Measure-Object).Count
Select-String -Path (Join-Path $Repo 'lib\main.dart') -Pattern 'v3.8-fix17'
Select-String -Path (Join-Path $Repo 'pubspec.yaml') -Pattern '3.8.11\+17'
Select-String -Path (Join-Path $Repo 'lib\data\mock_data.dart') -Pattern 'resetRuntimeDemoData'
Select-String -Path (Join-Path $Repo 'lib\data\registration_store.dart') -Pattern 'تم تفريغ جميع البيانات الحالية|resetRuntimeDemoData'

Write-Host 'OK: fix17 applied successfully.' -ForegroundColor Green
